import {readingWorkflowMarkup,updateReadingWorkflow,bindReadingWorkflow,focusReadingTarget} from './literature-workflow.mjs';
import {esc,icon} from './ui.mjs';
import {newReferenceSearchItems,pubmedSourceNotice} from './writing-reference-search.mjs';

const providers={crossref:'Crossref',europepmc:'Europe PMC',pubmed:'PubMed',openalex:'OpenAlex',semantic_scholar:'Semantic Scholar',arxiv:'arXiv',aminer:'AMiner'};
const types={all:'全部类型',journal:'期刊论文',thesis:'学位论文',book:'学术图书',report:'技术报告',chapter:'书籍章节',preprint:'预印本',conference:'会议论文',other:'其他'};
const preprintSorts=['submittedDate','lastUpdatedDate'];
function stylesheet(doc){if(doc.querySelector('[data-literature-discovery-style]'))return;const link=doc.createElement('link');link.rel='stylesheet';link.href='/workspace/literature-discovery.css';link.dataset.literatureDiscoveryStyle='';doc.head.append(link);}
export function literatureDiscoveryQuery(form,page=1){
 const value=new FormData(form),q=String(value.get('q')||'').trim().replace(/\s+/g,' ');
 if(q.length<2||q.length>200)throw Error('请输入 2～200 字符的公开标题、关键词或 DOI。');
 const sort=String(value.get('sort')||'relevance'),source=preprintSorts.includes(sort)?'arxiv':'all',query={q,source,type:String(value.get('type')||'all'),sort,page:String(page),limit:'20'};
 if(!Object.hasOwn(types,query.type)||!['relevance','year','citations','submittedDate','lastUpdatedDate'].includes(query.sort))throw Error('请选择有效的类型和排序方式。');
 if(!Number.isInteger(page)||page<1||page>5)throw Error('当前检索窗口最多支持 5 页。');
 for(const name of ['yearFrom','yearTo']){const year=String(value.get(name)||'').trim();if(year){if(!/^\d{4}$/.test(year)||Number(year)<1000||Number(year)>new Date().getFullYear()+1)throw Error('请填写有效的四位年份，或留空。');query[name]=year;}}
 if(query.yearFrom&&query.yearTo&&query.yearFrom>query.yearTo)throw Error('起始年份不能晚于结束年份。');
 for(const name of ['hasDoi','hasCitations','openAccess'])if(value.get(name))query[name]='true';
 if(source==='arxiv'){
  const range=String(value.get('dateRange')||'all');if(!['all','7','30'].includes(range))throw Error('请选择有效的提交时间范围。');
  if(range!=='all'){const now=new Date(),end=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()));query.dateTo=end.toISOString().slice(0,10);end.setUTCDate(end.getUTCDate()-Number(range)+1);query.dateFrom=end.toISOString().slice(0,10);}
 }
 return query;
}

/** Read-only discovery; bibliography import and abstract adoption are separate explicit actions. */
export function mountLiteratureDiscovery({container,modal,notify=()=>{},getExisting=()=>[],onImport,onReadAbstract,onOpenMetadata,compact=false,fetcher=(...args)=>fetch(...args)}={}){
 if(!container||typeof onImport!=='function')throw Error('文献检索工作区缺少导入操作。');
 const doc=container.ownerDocument,win=doc.defaultView,initialHash=win.location.hash;stylesheet(doc);
 let savedCount=0,outcome='',flowError='',errorStep=1;let live=true,request=0,controller=null,capController=null,timer=null,capTimer=null,busy=false,importing=false,dirty=false,items=[],lastQuery=null,page=1,hasMore=false,available=['crossref','europepmc','pubmed','arxiv'];
 const selected=new Set(),imported=[],disposers=[],$=s=>container.querySelector(s),current=()=>live&&container.isConnected&&win.location.hash===initialHash;
 const listen=(node,type,fn)=>{node?.addEventListener(type,fn);disposers.push(()=>node?.removeEventListener(type,fn));};
 const existing=()=>[...(Array.isArray(getExisting())?getExisting():[]),...imported];
 const isExisting=row=>newReferenceSearchItems([row],existing()).length===0;
 function message(value,error=false){if(current()){$(error?'[data-ld-error]':'[data-ld-status]').textContent=value;if(error)flowError=value;updateWorkflow();}}
 container.innerHTML=`<section class="lit-discovery${compact?' lit-discovery-compact':''}" aria-labelledby="ld-title">
 <header class="ld-intro"><div><span>RESEARCH DISCOVERY</span><h2 id="ld-title">找到值得深入研读的文献</h2><p>按研究主题查找文献，筛选后添加至我的文献，再继续阅读与引用。</p></div><span class="ld-intro-icon" aria-hidden="true">${icon('search',38)}</span></header>
 ${compact?'':readingWorkflowMarkup('discovery')}
 <form class="ld-form" data-unprotected><label for="ld-query">标题、关键词或 DOI</label><div class="ld-search-line"><input id="ld-query" name="q" type="search" minlength="2" maxlength="200" required placeholder="输入公开研究主题，英文关键词通常更易匹配"><button type="submit" class="btn primary">${icon('search',17)}检索文献</button></div>
 <details class="ld-filters" ${compact?'':'data-optional-fields open'}><summary>高级筛选 <span>类型、年份、引用与开放获取</span></summary><div class="ld-filter-grid"><label>文献类型<select name="type">${Object.entries(types).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><label>起始年份<input name="yearFrom" type="number" min="1000" max="${new Date().getFullYear()+1}" placeholder="不限"></label><label>结束年份<input name="yearTo" type="number" min="1000" max="${new Date().getFullYear()+1}" placeholder="不限"></label><label>排序<select name="sort"><option value="relevance">相关性</option><option value="year">发表年份优先</option><option value="citations">被引次数优先</option><option value="submittedDate" data-ld-preprint-option>最新预印本</option><option value="lastUpdatedDate" data-ld-preprint-option>预印本最近更新</option></select></label><label data-ld-date hidden>预印本提交时间（UTC）<select name="dateRange"><option value="all">不限时间</option><option value="7">近 7 天</option><option value="30">近 30 天</option></select></label></div><div class="ld-filter-checks"><label><input name="hasDoi" type="checkbox">仅有 DOI</label><label><input name="hasCitations" type="checkbox">已有被引记录</label><label><input name="openAccess" type="checkbox">仅开放获取</label></div><p>被引次数缺失不代表零；预印本可能尚未经过同行评审。</p></details></form>
 <div class="ld-request"><p data-ld-status role="status" aria-live="polite">${compact?'':'检索和引用转换不调用 AI，不扣科研积分。'}</p><button type="button" class="btn secondary" data-ld-cancel hidden>取消检索</button></div><p data-ld-error role="alert"></p>
 <div class="ld-search-wait" data-ld-wait hidden role="status"><span aria-hidden="true"></span><p>正在检索文献，请稍候。结果会自动显示，无需重复点击。</p></div>
 <section class="ld-results" data-ld-results aria-busy="false"><div class="ld-empty">${icon('book',34)}<h3>从一个清楚的研究问题开始</h3><p>查找真实文献，再核对摘要、出版信息与可用原文。</p></div></section>
 <footer class="ld-selection"><label><input type="checkbox" data-ld-select-all disabled>选择当前页</label><strong data-ld-selected>尚未选择</strong><button type="button" class="btn secondary" data-ld-citations disabled>转换所选引用</button><button type="button" class="btn primary" data-ld-import disabled>添加所选文献</button></footer>
 <nav class="ld-pagination" aria-label="检索结果分页"><button type="button" class="btn secondary" data-ld-prev disabled>上一页</button><span data-ld-page>尚无检索结果</span><button type="button" class="btn secondary" data-ld-next disabled>下一页</button></nav>
 <details class="ld-data-usage"><summary>数据使用说明</summary><p class="ld-boundary">每页展示最多 20 篇去重题录，最多浏览 5 页；本页条数不代表全部匹配数量。筛选基于当前可用题录，可能无法取得全部结果。保存题录不等于读取全文；只有明确选择摘要研读或导入正文后，才会成为文献研读材料。</p><p class="ld-attribution" data-ld-attribution-providers hidden></p><p class="ld-attribution" data-ld-arxiv-notice>Thank you to arXiv for use of its open access interoperability.</p><p class="ld-attribution" data-ld-pubmed-notice>${pubmedSourceNotice}</p></details></section>`;
 const form=$('form');
 function updateWorkflow(){
  const waiting=$('[data-ld-wait]');if(waiting)waiting.hidden=!busy;
  const nav=$('[data-reading-workflow]');if(!nav)return;let step=String(form.elements.q.value||'').trim().length>=2?2:1,phase=step===2?'review':'prepare',hint=step===2?'核对检索主题与筛选条件，点击“检索文献”开始。':'输入研究主题、文献标题或 DOI，开始检索。';
  if(busy){step=2;phase='searching';hint='正在检索文献，结果会自动更新；可取消本次检索。';}
  else if(importing){step=3;phase='saving';hint='正在保存所选文献，请稍候，无需重复点击。';}
  else if(flowError){step=errorStep;phase='failed';hint=flowError;}
  else if(outcome==='cancelled'){step=2;phase='cancelled';hint='检索已取消；原有文献仍保留，可调整条件后重新检索。';}
  else if(dirty){step=1;phase='review';hint='检索条件已变化，请重新检索；上次结果仍保留供查看。';}
  else if(savedCount){step=4;phase='complete';hint=`已保存 ${savedCount} 篇文献，可从“我的文献”继续核对与研读。`;}
  else if(items.length){step=3;phase='select';hint=selected.size?`已选择 ${selected.size} 篇，可保存文献或转换引用。`:'已取得检索结果，请核对题录与摘要，再选择要保留的文献。';}
  else if(lastQuery){step=2;phase='empty';hint='本次没有匹配结果，可减少关键词或扩大筛选范围后重试。';}
  updateReadingWorkflow(nav,{step,phase,hint,disabled:[...(!items.length||dirty||busy||importing?[3]:[]),...(!savedCount?[4]:[])]});
  const wait=$('[data-ld-wait]');if(wait)wait.hidden=!busy;
 }
 bindReadingWorkflow($('[data-reading-workflow]'),step=>focusReadingTarget($(step===1?'[name="q"]':step===2?'.ld-form':step===3?'[data-ld-results]':'.ld-selection')));

 function preprintControls(){const enabled=available.includes('arxiv');for(const node of form.querySelectorAll('[data-ld-preprint-option]')){node.hidden=!enabled;node.disabled=importing||!enabled;}if(!enabled&&preprintSorts.includes(form.elements.sort.value))form.elements.sort.value='relevance';const recent=enabled&&preprintSorts.includes(form.elements.sort.value);$('[data-ld-date]').hidden=!recent;form.elements.dateRange.disabled=importing||!recent;}
 function usageNotes(){const supplied=new Set(items.flatMap(row=>[row.source,...(row.sourceProvenance||[]).map(value=>value.source)]));$('[data-ld-arxiv-notice]').hidden=!available.includes('arxiv')&&!supplied.has('arxiv');$('[data-ld-pubmed-notice]').hidden=!available.includes('pubmed')&&!supplied.has('pubmed');const names=[...supplied].filter(id=>id!=='arxiv'&&id!=='pubmed'&&Object.hasOwn(providers,id)).map(id=>providers[id]),note=$('[data-ld-attribution-providers]');note.hidden=!names.length;note.textContent=names.length?'题录数据由 '+names.join('、')+' 提供；引用时请核对文献详情与出版信息。':'';}
 function controls(){for(const node of form.querySelectorAll('input,select,button'))node.disabled=importing;preprintControls();const eligible=items.filter(row=>!isExisting(row)),count=eligible.filter(row=>selected.has(row.id)).length;for(const box of container.querySelectorAll('[data-ld-pick]')){const row=items.find(item=>item.id===box.dataset.ldPick);box.disabled=busy||importing||dirty;box.checked=!!row&&selected.has(row.id);}$('[data-ld-import]').disabled=!count||busy||importing||dirty;$('[data-ld-citations]').disabled=!selected.size||busy||importing||dirty;$('[data-ld-selected]').textContent=selected.size?`已选 ${selected.size} 篇`:'尚未选择';$('[data-ld-import]').textContent=importing?'正在保存…':count?`添加 ${count} 篇文献`:'添加所选文献';const all=$('[data-ld-select-all]');all.disabled=!items.length||busy||importing||dirty;all.checked=!!items.length&&selected.size===items.length;all.indeterminate=selected.size>0&&selected.size<items.length;$('[data-ld-prev]').disabled=busy||importing||dirty||page<=1||!lastQuery;$('[data-ld-next]').disabled=busy||importing||dirty||!hasMore||page>=5;$('[data-ld-page]').textContent=lastQuery?`第 ${page} 页 · 本页 ${items.length} 篇`:'尚无检索结果';if(compact){$('[data-ld-results]').hidden=!lastQuery&&!busy;$('[data-ld-results]').dataset.hasQuery=String(!!lastQuery);$('[data-ld-import]').closest('footer').hidden=!items.length;$('[data-ld-prev]').closest('nav').hidden=!(page>1||hasMore);}$('[data-ld-cancel]').hidden=!busy;$('[data-ld-results]').setAttribute('aria-busy',String(busy));$('[data-ld-results]').hidden=compact&&!lastQuery||busy&&!lastQuery||!!flowError&&!items.length;for(const node of container.querySelectorAll('[data-ld-abstract-read],[data-ld-citation-one],[data-ld-open]'))node.disabled=busy||importing||dirty;updateWorkflow();}
 function renderResults(){
  usageNotes();
  $('[data-ld-results]').innerHTML=items.length?`<header class="ld-result-heading"><h3>本页取得 ${items.length} 篇题录</h3><p>检索词：${esc(lastQuery.q)} · 第 ${page} 页</p></header>${items.map((row,index)=>`<article class="ld-result"><div class="ld-result-top"><label><input type="checkbox" data-ld-pick="${esc(row.id)}"><span><small>${String(index+1).padStart(2,'0')} · ${esc(types[row.documentType]||types[row.type]||'文献')}</small>${compact?`<button type="button" class="ld-open-title" data-ld-open="${esc(row.id)}" aria-label="${row.abstract?'阅读摘要':'打开文献'}：${esc(row.title)}">${esc(row.title)}</button>`:`<b>${esc(row.title)}</b>`}</span></label><span class="ld-tag">${isExisting(row)?'已保存':'题录 · 未读取全文'}</span></div><p class="ld-authors">${esc(row.authors||'作者未提供')} · ${esc(row.year||'年份未提供')}${row.journal||row.venue?' · '+esc(row.journal||row.venue):''}</p><div class="ld-record-meta">${row.doi?`<span>DOI ${esc(row.doi)}</span>`:''}${Number.isSafeInteger(row.citationCount)?`<span>被引 ${row.citationCount} 次</span>`:row.citationBucket?`<span>被引区间 ${esc(row.citationBucket)} · 非精确次数</span>`:'<span>被引次数未提供</span>'}${row.openAccess===true?'<span class="ld-oa">开放获取</span>':''}</div>${row.abstract?`<details class="ld-abstract"><summary>查看摘要</summary><p>${esc(row.abstract)}</p><small>仅摘要，尚未读取全文。</small></details>`:''}<div class="ld-row-actions">${row.url?`<a href="${esc(row.url)}" target="_blank" rel="noopener noreferrer">文献详情 ↗</a>`:''}${row.fullTextUrl&&row.fullTextUrl!==row.url?`<a href="${esc(row.fullTextUrl)}" target="_blank" rel="noopener noreferrer">公开原文入口 ↗</a>`:''}<button type="button" class="btn secondary" data-ld-citation-one="${esc(row.id)}">转换引用</button>${compact?`<button type="button" class="btn primary" data-ld-open="${esc(row.id)}">${row.abstract?'阅读摘要':'打开文献'}</button>`:''}${!compact&&row.abstract&&onReadAbstract?`<button type="button" class="btn secondary" data-ld-abstract-read="${esc(row.id)}">用摘要开始研读</button>`:''}</div></article>`).join('')}`:`<div class="ld-empty">${icon('search',30)}<h3>没有找到匹配文献</h3><p>可以扩大年份范围，或减少关键词与筛选条件后重试。</p></div>`;
  controls();
 }
 function changed(){if(importing)return;savedCount=0;outcome='';flowError='';request++;controller?.abort();clearTimeout(timer);busy=false;selected.clear();dirty=!!lastQuery;controls();if(lastQuery)message('条件已变化，请重新检索后再选择文献；上次结果保留供查看。');}
 async function search(wantedPage=1){if(!current()||importing)return;savedCount=0;outcome='';flowError='';errorStep=1;let query;try{query=literatureDiscoveryQuery(form,wantedPage);}catch(error){message(error.message,true);return;}errorStep=2;request++;const seq=request;controller?.abort();clearTimeout(timer);const abort=new win.AbortController();controller=abort;let timedOut=false,failure='文献检索未完成，请稍后重试。';selected.clear();busy=true;dirty=false;message('',true);message('正在检索文献，请稍候…');controls();timer=win.setTimeout(()=>{timedOut=true;abort.abort();},query.source==='arxiv'?32000:22000);
  try{const response=await fetcher('/api/literature/search?'+new URLSearchParams(query),{method:'GET',credentials:'same-origin',cache:'no-store',signal:abort.signal,headers:{Accept:'application/json'}});const body=await response.json();if(!current()||seq!==request)return;if(abort.signal.aborted)throw Error();if(!response.ok){items=[];lastQuery=query;page=wantedPage;hasMore=false;renderResults();failure=response.status===429?'检索较频繁，请稍后再试。':'暂时无法完成文献检索，请稍后重试。';throw Error();}if(!Array.isArray(body.items)||body.items.length>20||body.page!==undefined&&body.page!==wantedPage){failure='检索结果不完整，请稍后重试。';throw Error();}items=newReferenceSearchItems(body.items);lastQuery=query;page=wantedPage;hasMore=body.hasMore===true;renderResults();message(body.partial?`已取得 ${items.length} 篇题录；部分结果暂未取得，可先查看已有文献或稍后重试。`:`已取得 ${items.length} 篇题录，可添加所选文献或转换引用。`);}
  catch{if(current()&&seq===request){dirty=!!lastQuery;if(abort.signal.aborted&&!timedOut)message('检索已取消，已保存文献不受影响。');else message(timedOut?'本次检索超时，请稍后再试。':failure,true);}}
  finally{if(current()&&seq===request){busy=false;clearTimeout(timer);controller=null;controls();}}
 }
 async function citations(rows){if(!rows.length||busy||importing||dirty)return;try{const {openLiteratureCitations}=await import('./literature-citations.mjs');if(current())openLiteratureCitations({papers:rows,modal,notify});}catch{if(current())message('引用转换暂时无法打开，请稍后重试。',true);}}
 async function openRow(row){if(!row||busy||importing||dirty||!current())return;importing=true;controls();try{const open=row.abstract?onReadAbstract:onOpenMetadata;if(!open)throw Error('请先保存文献，再补充要研读的原文。');await open(structuredClone(row),{isCurrent:current});}catch(error){if(current())message(error.message||'文献暂时无法打开，请重试。',true);}finally{importing=false;if(current())controls();}}
 async function adoptAbstract(row){if(!onReadAbstract||busy||importing||dirty||!row?.abstract)return;if(compact){await openRow(row);return;}const id='ld-abstract-'+row.id.replace(/[^\w-]/g,'');modal('确认以摘要研读',`<section id="${id}"><p>本次仅将数据库实际提供的摘要作为研读材料，未取得全文；此操作不会调用 AI 或扣除积分。</p><h3>${esc(row.title)}</h3><pre class="ld-abstract-preview">${esc(row.abstract)}</pre><button type="button" class="btn primary" data-ld-confirm-abstract>确认摘要并打开研读</button><p role="alert" data-ld-abstract-error></p></section>`);const host=doc.getElementById(id);if(!host)return;host.querySelector('[data-ld-confirm-abstract]').onclick=async()=>{if(!current()||!host.isConnected)return;const button=host.querySelector('button');button.disabled=true;try{await onReadAbstract(structuredClone(row),{isCurrent:()=>current()&&host.isConnected});if(host.isConnected)host.closest('dialog')?.close();}catch(error){if(host.isConnected){host.querySelector('[data-ld-abstract-error]').textContent=error.message||'摘要未能保存，请重试。';button.disabled=false;}}};}
 listen(form,'submit',event=>{event.preventDefault();void search(1);});
 listen(form,'input',changed);listen(form,'change',changed);
 listen($('[data-ld-cancel]'),'click',()=>{outcome='cancelled';savedCount=0;flowError='';request++;controller?.abort();clearTimeout(timer);busy=false;dirty=!!lastQuery;selected.clear();message('已取消检索，上次结果仅供查看；请重新检索后再选择。');controls();});
 listen($('[data-ld-select-all]'),'change',event=>{for(const row of items){if(event.target.checked)selected.add(row.id);else selected.delete(row.id);}controls();});
 listen($('[data-ld-results]'),'change',event=>{const box=event.target.closest('[data-ld-pick]');if(!box||busy||dirty||importing)return;box.checked?selected.add(box.dataset.ldPick):selected.delete(box.dataset.ldPick);controls();});
 listen($('[data-ld-results]'),'click',event=>{const open=event.target.closest('[data-ld-open]');if(open){event.preventDefault();event.stopPropagation();void openRow(items.find(row=>row.id===open.dataset.ldOpen));return;}const cite=event.target.closest('[data-ld-citation-one]'),read=event.target.closest('[data-ld-abstract-read]');if(cite)void citations(items.filter(row=>row.id===cite.dataset.ldCitationOne));if(read)void adoptAbstract(items.find(row=>row.id===read.dataset.ldAbstractRead));});
 listen($('[data-ld-citations]'),'click',()=>void citations(items.filter(row=>selected.has(row.id))));
 listen($('[data-ld-import]'),'click',async()=>{if(!current()||busy||dirty||importing)return;const rows=newReferenceSearchItems(items.filter(row=>selected.has(row.id)),existing());if(!rows.length)return;errorStep=3;importing=true;message('',true);controls();try{await onImport(rows,{isCurrent:current});if(current()){savedCount=rows.length;imported.push(...rows);selected.clear();renderResults();message(`已将 ${rows.length} 篇题录添加至我的文献；正文与摘要研读范围仍需确认。`);}}catch(error){if(current())message(error.message||'文献未能保存，当前选择保留，请重试。',true);}finally{importing=false;if(current())controls();}});
 listen($('[data-ld-prev]'),'click',()=>void search(page-1));listen($('[data-ld-next]'),'click',()=>void search(page+1));
 function dispose(){if(!live)return;live=false;request++;clearTimeout(timer);clearTimeout(capTimer);controller?.abort();capController?.abort();disposers.splice(0).forEach(remove=>remove());observer?.disconnect();}
 listen(win,'hashchange',dispose);let observer=null;if(win.MutationObserver){observer=new win.MutationObserver(()=>{if(live&&!container.isConnected)dispose();});observer.observe(doc.body,{childList:true,subtree:true});}
 const ready=(async()=>{const abort=new win.AbortController();capController=abort;capTimer=win.setTimeout(()=>abort.abort(),4000);try{const response=await fetcher('/api/capabilities',{credentials:'same-origin',cache:'no-store',signal:abort.signal});if(!response.ok)return;const body=await response.json();if(!current()||abort.signal.aborted||!Array.isArray(body.academicSearchSources))return;const recent=preprintSorts.includes(form.elements.sort.value);available=[...new Set(body.academicSearchSources.filter(id=>Object.hasOwn(providers,id)))];if(recent&&!available.includes('arxiv')){form.elements.sort.value='relevance';changed();message('预印本检索暂时不可用，已恢复相关性排序。');}else controls();usageNotes();}catch{}finally{clearTimeout(capTimer);capController=null;}})();
 controls();return{dispose,ready,search:()=>search(1)};
}
